      "replace": "@staticmethod
	def _modifiers(modifiers: list[Literal['Alt', 'Control', 'Meta', 'Shift']] | None) -> int:
		"""Return the combined modifier bitmask.

		Accepts modifier names in any case (e.g., "alt", "Control", "SHIFT").
		Raises a ValueError if an unknown modifier is supplied.
		"""
		bits = {'alt': 1, 'control': 2, 'meta': 4, 'shift': 8}
		if not modifiers:
			return 0
		# Normalize to lowercase for case‑insensitive matching
		normalized = [m.lower() for m in set(modifiers)]
		unknown = [m for m in normalized if m not in bits]
		if unknown:
			raise ValueError(f'Unknown modifier(s): {unknown}')
		return sum(bits[m] for m in normalized)"
    }
  ],
  "summary": "Updated Mouse._modifiers to be case‑insensitive by normalizing input strings to lowercase, adding documentation, and validating unknown modifiers. This prevents errors when modifiers like ['Alt','control','SHIFT'] are provided."
}

